const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Whakaari/White Island coordinates
  const volcano = ee.Geometry.Point([177.18, -37.52]);

  // Define regions to check plume direction
  const southRegion = ee.Geometry.Point([177.18, -37.62]); // 10km south
  const northRegion = ee.Geometry.Point([177.18, -37.42]); // 10km north
  const eastRegion = ee.Geometry.Point([177.28, -37.52]); // 10km east
  const westRegion = ee.Geometry.Point([177.08, -37.52]); // 10km west

  // Search for Sentinel-2 imagery on January 7, 2025
  let collection = ee.ImageCollection('COPERNICUS/S2_HARMONIZED')
    .filterBounds(volcano)
    .filterDate('2025-01-07', '2025-01-08')
    .sort('CLOUDY_PIXEL_PERCENTAGE');

  let size = collection.size().getInfo();
  console.log(`Sentinel-2 images found: ${size}`);

  // Fallback to Landsat if no Sentinel-2
  if (size === 0) {
    collection = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
      .filterBounds(volcano)
      .filterDate('2025-01-07', '2025-01-08');
    size = collection.size().getInfo();
    console.log(`Landsat-9 images found: ${size}`);
  }

  if (size === 0) {
    console.log('No images available for January 7, 2025');
    console.log('<answer>C1</answer>');
    return;
  }

  // Get the first (least cloudy) image
  const image = collection.first();

  // Use aerosol band (B1 for Sentinel-2) or TrueColor composite
  let aerosolBand = image.select(['B1', 'B2', 'B4'], ['aerosol', 'blue', 'red']);

  // Sample aerosol values in each direction
  const southVal = aerosolBand.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: southRegion.buffer(2000),
    scale: 1000,
    maxPixels: 1e9
  }).get('aerosol').getInfo();

  const northVal = aerosolBand.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: northRegion.buffer(2000),
    scale: 1000,
    maxPixels: 1e9
  }).get('aerosol').getInfo();

  const eastVal = aerosolBand.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: eastRegion.buffer(2000),
    scale: 1000,
    maxPixels: 1e9
  }).get('aerosol').getInfo();

  const westVal = aerosolBand.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: westRegion.buffer(2000),
    scale: 1000,
    maxPixels: 1e9
  }).get('aerosol').getInfo();

  console.log(`Aerosol values - South: ${southVal}, North: ${northVal}, East: ${eastVal}, West: ${westVal}`);

  if (southVal === null || southVal === undefined) {
    console.log('Failed to calculate aerosol values');
    console.log('<answer>C3</answer>');
    return;
  }

  // Check if plume travels south (higher aerosol values to the south)
  const maxOther = Math.max(northVal || 0, eastVal || 0, westVal || 0);

  console.log(`Max aerosol in other directions: ${maxOther}`);
  console.log(`South aerosol ratio: ${(southVal / maxOther).toFixed(2)}`);

  // Plume travels south if southern values significantly higher
  if (southVal > maxOther * 1.2) {
    console.log('Plume direction: SOUTH');
    console.log('<answer>A</answer>');
  } else {
    console.log('Plume direction: NOT primarily south');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
